window.armazenamento={CHAVE_RASCUNHO:"ong_rascunho_cadastro",salvarRascunho(){let e=document.querySelector("form");if(!e)return;let r={};e.querySelectorAll('input[type="text"], input[type="email"], input[type="tel"], input[type="date"], textarea').forEach(e=>{e.name&&(r[e.name]=e.value)});let t={};e.querySelectorAll('input[type="checkbox"]').forEach(e=>{e.name&&(t[e.name]||(t[e.name]=[]),e.checked&&t[e.name].push(e.value))}),r.__checkboxes=t;try{localStorage.setItem(this.CHAVE_RASCUNHO,JSON.stringify(r))}catch(a){console.warn("N\xe3o foi poss\xedvel salvar o rascunho:",a)}},recuperarRascunho(){let e=document.querySelector("form");if(!e)return;let r=localStorage.getItem(this.CHAVE_RASCUNHO);if(r)try{let t=JSON.parse(r);Object.keys(t).forEach(r=>{if("__checkboxes"===r)return;let a=e.querySelector(`[name="${r}"]`);a&&(a.value=t[r])}),t.__checkboxes&&Object.keys(t.__checkboxes).forEach(r=>{let a=t.__checkboxes[r];e.querySelectorAll(`input[name="${r}"]`).forEach(e=>{e.checked=a.includes(e.value)})})}catch(a){console.warn("Rascunho corrompido, ignorando:",a)}},limparRascunho(){localStorage.removeItem(this.CHAVE_RASCUNHO)},iniciar(){document.addEventListener("rota-renderizada",()=>{setTimeout(()=>this.recuperarRascunho(),50)})}};